def apply(root):
    try:
        import tkinter as tk
        root._pm_icon = tk.PhotoImage(data=PNG_B64)      # keep a reference or Tk drops it
        root.iconphoto(True, root._pm_icon)
    except Exception:
        pass
    if os.name == "nt":
        try:
            from . import system
            for base in (getattr(sys, "_MEIPASS", ""), system.app_dir()):
                if base:
                    ico = os.path.join(base, "assets", "phonemic.ico")
                    if os.path.isfile(ico):
                        root.iconbitmap(default=ico)
                        break
        except Exception:
            pass
